-- Specificity: local_pdf_report_engine_active (spec changes/local-pdf-report-engine)
-- ON  -> the OICR, Innovation and Cluster summary PDFs are rendered in-process by MARLO.
-- OFF -> the summary PDFs are generated by the reports microservice, exactly as before (unchanged behaviour).
--
-- Rollout: the engine is created OFF for every global unit, and a unit with no row reads as OFF too. To switch a unit
-- to the in-process engine, set its row to 'true', for example AICCRA:
--   UPDATE custom_parameters cp INNER JOIN parameters p ON p.id = cp.parameter_id
--   INNER JOIN global_units g ON g.id = cp.global_unit_id
--   SET cp.`value` = 'true'
--   WHERE p.`key` = 'local_pdf_report_engine_active' AND g.acronym = 'AICCRA';
--
-- New units: a global unit created later gets its row from GlobalUnitCreationManagerImpl.initializeCustomParameters,
-- which saves one custom parameter per specificity of the unit's type. A unit created from a template unit that has
-- the flag on inherits 'true' (boolean specificities are inheritable); this is accepted, because the template unit has
-- already validated the engine. Units of a type other than 1, 3 or 4 get no row, as with every specificity of this kind.
--
-- Safe in every environment:
-- * the parameter inserts are guarded, because parameters has no unique index on `key` and a retry after a failed
--   attempt would otherwise duplicate them;
-- * no global unit, parameter or user id is assumed; units are matched through their global unit type, and a database
--   with no global units only receives the parameters rows;
-- * every unit gets an explicit 'false' row: ValidSessionCrpInterceptor only replaces the keys the new unit has
--   rows for, so a missing row would keep a stale 'true' in the session after switching from a unit that has it on;
-- * created_by and modified_by resolve the seed account 3 when it exists and NULL when it does not;
-- * DML only, so Flyway's transaction covers the whole script, and a second run changes 0 rows.

INSERT INTO parameters (global_unit_type_id, `key`, `description`, `format`, default_value, category)
SELECT '1', 'local_pdf_report_engine_active', 'Render the OICR, Innovation and Cluster summary PDFs inside MARLO instead of calling the reports microservice.', '1', 'false', '2'
WHERE NOT EXISTS (SELECT 1 FROM parameters WHERE `key` = 'local_pdf_report_engine_active' AND global_unit_type_id = '1');

INSERT INTO parameters (global_unit_type_id, `key`, `description`, `format`, default_value, category)
SELECT '3', 'local_pdf_report_engine_active', 'Render the OICR, Innovation and Cluster summary PDFs inside MARLO instead of calling the reports microservice.', '1', 'false', '2'
WHERE NOT EXISTS (SELECT 1 FROM parameters WHERE `key` = 'local_pdf_report_engine_active' AND global_unit_type_id = '3');

INSERT INTO parameters (global_unit_type_id, `key`, `description`, `format`, default_value, category)
SELECT '4', 'local_pdf_report_engine_active', 'Render the OICR, Innovation and Cluster summary PDFs inside MARLO instead of calling the reports microservice.', '1', 'false', '2'
WHERE NOT EXISTS (SELECT 1 FROM parameters WHERE `key` = 'local_pdf_report_engine_active' AND global_unit_type_id = '4');

INSERT INTO custom_parameters (parameter_id, `value`, created_by, is_active, active_since, modified_by, modification_justification, global_unit_id)
SELECT p.id, 'false', (SELECT u.id FROM users u WHERE u.id = 3), 1, NOW(),
  (SELECT u.id FROM users u WHERE u.id = 3), 'local-pdf-report-engine: summary PDFs stay on the reports microservice', g.id
FROM global_units AS g
INNER JOIN parameters AS p ON p.global_unit_type_id = g.global_unit_type_id
WHERE p.`key` = 'local_pdf_report_engine_active'
  AND NOT EXISTS (SELECT 1 FROM custom_parameters cp WHERE cp.parameter_id = p.id AND cp.global_unit_id = g.id);
